    private val locationMap: Map<String, PoliceGpsLocation> by lazy {
        val map = mutableMapOf<String, PoliceGpsLocation>()
        for (loc in allLocations) {
            val key = normalize(loc.station)
            if (key.isNotBlank() && !map.containsKey(key)) {
                map[key] = loc
            }
            val divKey = normalize(loc.division)
            if (key.isNotBlank() && divKey.isNotBlank()) {
                map[key + divKey] = loc
            }
        }
        map
    }

    fun findLocation(stationName: String): PoliceGpsLocation? {
        val clean = normalize(stationName)
        if (clean.isBlank()) return null

        val aliasKey = aliases[clean]
        if (aliasKey != null && locationMap.containsKey(aliasKey)) {
            return locationMap[aliasKey]
        }

        locationMap[clean]?.let { return it }

        for ((k, loc) in locationMap) {
            if (k.length >= 4 && (clean.contains(k) || k.contains(clean))) {
                return loc
            }
        }

        for ((aliasK, aliasV) in aliases) {
            if (clean.contains(aliasK)) {
                val replaced = clean.replace(aliasK, aliasV)
                locationMap[replaced]?.let { return it }
                for ((k, loc) in locationMap) {
                    if (k.length >= 4 && (replaced.contains(k) || k.contains(replaced))) {
                        return loc
                    }
                }
            }
        }

        return null
    }

    fun enrichContact(contact: PoliceContact): PoliceContact {
        val loc = findLocation(contact.stationOrDesignation)
        val finalCoords = when {
            contact.locationCoordinates.isNotBlank() -> contact.locationCoordinates
            loc != null -> "${loc.lat},${loc.lng}"
            else -> ""
        }
        val finalAddress = when {
            contact.locationAddress.isNotBlank() -> contact.locationAddress
            loc != null -> if (loc.address.isNotBlank()) loc.address else "${loc.station}, ${loc.division}"
            else -> ""
        }
        return contact.copy(
            locationCoordinates = finalCoords,
            locationAddress = finalAddress
        )
    }
